{
  "sql": "SELECT id, match_id, scorer_player_id, minute, goal_type, assist_player_id, count(*) OVER () AS total_rows FROM world_cup.world_cup.goals WHERE assist_player_id IS NULL ORDER BY id LIMIT 50",
  "datasourceId": "cd08af5f-184e-4993-8f1a-0a49e2ae6051",
  "rationale": "Show the goal records that have no assisting player, which is what the completeness finding on goals.assist_player_id measured.",
  "limit": 50
}
